param([string]$RepositoryRoot=(Split-Path -Parent (Split-Path -Parent $PSScriptRoot)))
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot '../lib/Stage3StaticAudit.Common.ps1')
$source=[IO.File]::ReadAllText((Join-Path $RepositoryRoot 'tests/fixtures/AICF_MobDecisionProbe.c'))
$audit=[pscustomobject]@{Source=$source;Code=(ConvertTo-AICFCodeText $source)}
function MobBody([string]$Name){Get-AICFMethodBody $audit $Name}
$controller=[IO.File]::ReadAllText((Join-Path $RepositoryRoot 'AIConflictCore/Scripts/Game/AIConflict/Bootstrap/AICF_MatchController.c'))
$controllerAudit=[pscustomobject]@{Source=$controller;Code=(ConvertTo-AICFCodeText $controller)}
$methods=@('ResolveAllowedIdleReason','TryApplyHiddenMobEgressRecovery','TryFindDistinctMobEgressDestination')
foreach($name in $methods){
 if(!(Get-AICFMethodBody $controllerAudit $name)){throw "Original project declaration missing $name"}
 $body=MobBody $name
 if(@([regex]::Matches($body,('super\.'+[regex]::Escape($name)+'\('))).Count-ne1-or!$body.Contains('return actual;')){throw "Original decision must run exactly once and return unchanged $name"}
 if($body-match'\b(?:ReserveUnits|Set\w*|Fail|Cancel|CustomEvaluate|FindAllEmptyTerrainPositions|RequestAvailability|UpdateInteractor)\s*\('){throw "Observer mutates/re-evaluates $name"}
}
if($source-match'\b(?:CallLater|InsertEvent|SetWorldTransform|SetOrigin|SetHealth\w*|SetLifeState|SetLimitOfActiveAIs|FindAllEmptyTerrainPositions|CustomEvaluate|ShouldSuppressCluster|IsFormationAtWaypoint)\s*\('){throw 'Observer must not add timers, mutations or repeat native decisions'}
foreach($required in @('aicfMobDecisionProbe','MAX_RECORDS = 32','MAX_MEMBERS = 32','observations_incomplete=1','scope_current_after=','non_atomic=1','phase=BEFORE_PARENT','phase=AFTER','candidate_rejections=UNOBSERVED','extra_queries=0','slot.HasPendingOrderRecovery()','slot.HasFailedMovement()','slot.IsApproachRouteWaypoint()','slot.GetPlayerStrategicIntentTargetPosition()','mobOwner = frame.m_MainBase.GetOwner()','groupUtility.GetCurrentAction()','groupUtility.GetExecutedAction()','groupUtility.GetThreatMeasure()','waypoint_distance_m=','leader_waypoint_distance_m=','controller_present=','parent_exact=','access.IsInCompartment()')){if(!$source.Contains($required)){throw "Required observation missing $required"}}
$cause=MobBody Cause
if(!$cause.Contains('SCR_AIActionBase.Cast(action)')-or@([regex]::Matches($cause,'nativeAction.GetCause\(')).Count-ne1){throw 'GetCause belongs to pinned SCR_AIActionBase, not engine AIActionBase'}
$pinned=Join-Path $RepositoryRoot '.cache/reforger-api/Arma-Reforger-Script-Diff-1.8.0.13/scripts/Game/AI/Behavior/SCR_AIAction.c'
if(!(Test-Path $pinned)-or[IO.File]::ReadAllText($pinned)-notmatch'\bint\s+GetCause\s*\('){throw 'Pinned1.8.0.13 GetCause declaration unavailable'}
$idle=(MobBody ResolveAllowedIdleReason).Replace('super.','base.')
$hidden=(MobBody TryApplyHiddenMobEgressRecovery).Replace('super.','base.')
$nativeHiddenCall=[regex]::Match($hidden,'base\.TryApplyHiddenMobEgressRecovery\([\s\S]*?\);').Value
$convertedHiddenCall=$nativeHiddenCall.Replace('mainBase, recoveryDestination, nearestPlayerMeters,','mainBase, out recoveryDestination, out nearestPlayerMeters,').Replace('relocatedMembers, playerClearance, losClearance, combatClearance, rejectionReason);','out relocatedMembers, out playerClearance, out losClearance, out combatClearance, out rejectionReason);')
$hidden=$hidden.Replace($nativeHiddenCall,$convertedHiddenCall)
$find=(MobBody TryFindDistinctMobEgressDestination).Replace('super.','base.').Replace('reservedDestinations, destination);','reservedDestinations, out destination);')
$want=(MobBody Want).Replace('s_Keys.Count()','s_Keys.Count').Replace('s_Keys.Insert(key)','s_Keys.Add(key)')
$end=MobBody End
$stop=MobBody Stop
$write=(MobBody Write).Replace('s_Keys.Count()','s_Keys.Count').Replace('foreach (string beforeLine : frame.m_Before.m_Lines)','foreach (string beforeLine in frame.m_Before.m_Lines)').Replace('foreach (string afterLine : after.m_Lines)','foreach (string afterLine in after.m_Lines)')
$scope=MobBody ScopeLoss
$code=@'
using System;using System.Collections.Generic;
namespace MobDecisionReplay {
 public class N{public static implicit operator bool(N n){return n!=null;}}
 public class AICF_GroupSlot:N{} public class SCR_CampaignMilitaryBaseComponent:N{} public class SCR_CampaignFaction:N{} public class BaseWorld:N{} public class vector:N{} public class AICF_MobDecisionSnapshot:N{public List<string> m_Lines=new List<string>();public string m_sKey="S";} public class AICF_MobDecisionFrame:N{public int m_iSerial=7;public AICF_MobDecisionSnapshot m_Before=new AICF_MobDecisionSnapshot();public bool IsCurrent(){if(AICF_MobDecisionProbe.OnCurrent!=null)AICF_MobDecisionProbe.OnCurrent();return true;}}
 public class AIActionBase:N{} public class SCR_AIActionBase:AIActionBase{public int Calls,Result;public static SCR_AIActionBase Cast(AIActionBase a){return a as SCR_AIActionBase;}public int GetCause(){Calls++;return Result;}}
 public static class AICF_MobDecisionProbe{public const int MAX_RECORDS=32;public static AICF_MobDecisionFrame s_Frame;public static List<string> s_Keys=new List<string>();public static int s_iSerial,Logs,Writes,Ends;public static bool s_bOverflow,s_bScopeLoss,EnabledFlag=true;public static Action OnRead,OnCurrent;public static bool Enabled(){return EnabledFlag;}public static AICF_MobDecisionSnapshot Read(AICF_MobDecisionFrame f){if(OnRead!=null)OnRead();return new AICF_MobDecisionSnapshot();}public static void Print(string s){Logs++;if(s.Contains("event=DECISION"))Writes++;}public static AICF_MobDecisionFrame Begin(AICF_GroupSlot s,SCR_CampaignMilitaryBaseComponent b){if(!EnabledFlag)return null;s_Frame=new AICF_MobDecisionFrame();return s_Frame;}public static void Write(AICF_MobDecisionFrame frame,string stage,string actual,string inputs)WRITE public static void ScopeLoss()SCOPE public static bool Want(string key)WANT public static void End(AICF_MobDecisionFrame frame,AICF_MobDecisionFrame previous)END public static void Stop()STOP public static int Cause(AIActionBase action)CAUSE}
 public class Native{public int Calls;public bool Result;public Action During;public vector Destination=new vector();public AICF_GroupSlot ExpectedSlot;public SCR_CampaignMilitaryBaseComponent ExpectedBase;public SCR_CampaignFaction ExpectedFaction;public BaseWorld ExpectedWorld;public vector ExpectedMember,ExpectedTarget,ExpectedMob;public vector[] ExpectedReserved;public bool ExpectedLifecycle,ExpectedWait;protected string ResolveAllowedIdleReason(AICF_GroupSlot s,SCR_CampaignMilitaryBaseComponent b,bool l,bool w){if(s!=ExpectedSlot||b!=ExpectedBase||l!=ExpectedLifecycle||w!=ExpectedWait)throw new Exception("idle arguments");Calls++;if(During!=null)During();return Result?"PLAYER_POSITION_HOLD_AT_MOB":"NONE";}protected bool TryApplyHiddenMobEgressRecovery(AICF_GroupSlot s,SCR_CampaignFaction f,SCR_CampaignMilitaryBaseComponent b,out vector d,out float n,out int r,out string p,out string l,out string c,out string why){if(s!=ExpectedSlot||b!=ExpectedBase||f!=ExpectedFaction)throw new Exception("hidden arguments");Calls++;d=Destination;n=123.5f;r=3;p="P";l="L";c="C";why="WHY";if(During!=null)During();return Result;}protected bool TryFindDistinctMobEgressDestination(BaseWorld w,vector m,vector t,vector o,vector[] r,out vector d){if(w!=ExpectedWorld||m!=ExpectedMember||t!=ExpectedTarget||o!=ExpectedMob||r!=ExpectedReserved)throw new Exception("find arguments");Calls++;d=Destination;if(During!=null)During();return Result;}}
 public class Probe:Native{public string Idle(AICF_GroupSlot slot,SCR_CampaignMilitaryBaseComponent mainBase,bool vehicleLifecycle,bool safeVehicleSpawnWait)IDLE public bool Hidden(AICF_GroupSlot slot,SCR_CampaignFaction faction,SCR_CampaignMilitaryBaseComponent mainBase,out vector recoveryDestination,out float nearestPlayerMeters,out int relocatedMembers,out string playerClearance,out string losClearance,out string combatClearance,out string rejectionReason)HIDDEN public bool Find(BaseWorld world,vector memberOrigin,vector targetPosition,vector mobOrigin,vector[] reservedDestinations,out vector destination)FIND}
 public static class Cases{public static int Run(){int count=0;foreach(string stage in new[]{"idle","hidden","find"})foreach(bool enabled in new[]{false,true})foreach(bool result in new[]{false,true})foreach(string reentry in new[]{"none","stop","successor"}){AICF_MobDecisionProbe.Stop();AICF_MobDecisionProbe.EnabledFlag=enabled;AICF_MobDecisionProbe.OnRead=null;AICF_MobDecisionProbe.OnCurrent=null;AICF_MobDecisionProbe.Writes=0;var previous=new AICF_MobDecisionFrame();var successor=new AICF_MobDecisionFrame();AICF_MobDecisionProbe.s_Frame=previous;var p=new Probe{Result=result,ExpectedSlot=new AICF_GroupSlot(),ExpectedBase=new SCR_CampaignMilitaryBaseComponent(),ExpectedFaction=new SCR_CampaignFaction(),ExpectedWorld=new BaseWorld(),ExpectedMember=new vector(),ExpectedTarget=new vector(),ExpectedMob=new vector(),ExpectedReserved=new vector[0],ExpectedLifecycle=result,ExpectedWait=!result};if(reentry=="stop")p.During=()=>AICF_MobDecisionProbe.s_Frame=null;if(reentry=="successor")p.During=()=>AICF_MobDecisionProbe.s_Frame=successor;bool actual=false;if(stage=="idle")actual=p.Idle(p.ExpectedSlot,p.ExpectedBase,p.ExpectedLifecycle,p.ExpectedWait)=="PLAYER_POSITION_HOLD_AT_MOB";else if(stage=="hidden"){vector d;float n;int r;string a,b,c,why;actual=p.Hidden(p.ExpectedSlot,p.ExpectedFaction,p.ExpectedBase,out d,out n,out r,out a,out b,out c,out why);if(d!=p.Destination||n!=123.5f||r!=3||a!="P"||b!="L"||c!="C"||why!="WHY")throw new Exception("out changed");}else{vector d;actual=p.Find(p.ExpectedWorld,p.ExpectedMember,p.ExpectedTarget,p.ExpectedMob,p.ExpectedReserved,out d);if(d!=p.Destination)throw new Exception("destination changed");}if(actual!=result||p.Calls!=1||AICF_MobDecisionProbe.Writes!=(enabled&&reentry=="none"&&(stage!="idle"||!result)?1:0))throw new Exception(stage+" "+enabled+" "+result+" "+reentry);var expected=reentry=="stop"?null:reentry=="successor"?successor:previous;if(AICF_MobDecisionProbe.s_Frame!=expected)throw new Exception("successor overwritten");count++;}
 foreach(string boundary in new[]{"read","current"})foreach(bool successor in new[]{false,true}){AICF_MobDecisionProbe.Stop();AICF_MobDecisionProbe.EnabledFlag=true;AICF_MobDecisionProbe.Writes=0;AICF_MobDecisionProbe.OnRead=null;AICF_MobDecisionProbe.OnCurrent=null;var f=new AICF_MobDecisionFrame();var next=successor?new AICF_MobDecisionFrame():null;AICF_MobDecisionProbe.s_Frame=f;Action change=()=>AICF_MobDecisionProbe.s_Frame=next;if(boundary=="read")AICF_MobDecisionProbe.OnRead=change;else AICF_MobDecisionProbe.OnCurrent=change;AICF_MobDecisionProbe.Write(f,"TEST","NONE","");if(AICF_MobDecisionProbe.s_Frame!=next||AICF_MobDecisionProbe.Writes!=0||AICF_MobDecisionProbe.s_Keys.Count!=0||!AICF_MobDecisionProbe.s_bScopeLoss)throw new Exception("getter reentry "+boundary+successor);count++;}AICF_MobDecisionProbe.OnRead=null;AICF_MobDecisionProbe.OnCurrent=null;AICF_MobDecisionProbe.Stop();AICF_MobDecisionProbe.Logs=0;for(int i=0;i<32;i++){if(!AICF_MobDecisionProbe.Want("K"+i)||AICF_MobDecisionProbe.Want("K"+i))throw new Exception("distinct cap");count++;}if(AICF_MobDecisionProbe.Want("overflow")||AICF_MobDecisionProbe.Want("overflow2")||AICF_MobDecisionProbe.s_Keys.Count!=32||AICF_MobDecisionProbe.Logs!=1||!AICF_MobDecisionProbe.s_bOverflow)throw new Exception("overflow proof");count++;AICF_MobDecisionProbe.Stop();if(AICF_MobDecisionProbe.s_Frame||AICF_MobDecisionProbe.s_Keys.Count!=0||AICF_MobDecisionProbe.s_bOverflow)throw new Exception("stop");count++;
 foreach(int expected in new[]{0,1,4,8,16}){var action=new SCR_AIActionBase{Result=expected};if(AICF_MobDecisionProbe.Cause(action)!=expected||action.Calls!=1)throw new Exception("native cause");count++;}if(AICF_MobDecisionProbe.Cause(null)!=-1||AICF_MobDecisionProbe.Cause(new AIActionBase())!=-1)throw new Exception("unknown cause");return count+2;}}
}
'@
$code=$code.Replace('IDLE',$idle).Replace('HIDDEN',$hidden).Replace('FIND',$find).Replace('WANT',$want).Replace('END',$end).Replace('STOP',$stop).Replace('CAUSE',$cause).Replace('WRITE',$write).Replace('SCOPE',$scope)
Add-Type -TypeDefinition $code
$cases=[MobDecisionReplay.Cases]::Run()
$unsafe=0
foreach($mutation in @(@('result','return actual;','return !actual;'),@('filter','if (actual == "NONE")',''),@('end','if (frame && s_Frame == frame) s_Frame = previous;','s_Frame = previous;'),@('duplicate','if (s_Keys.Contains(key)) return false;',''),@('cap','if (s_Keys.Count >= MAX_RECORDS)','if (s_Keys.Count < 0)'),@('overflow','s_bOverflow = true;',''),@('readScope','if (s_Frame != frame) { ScopeLoss(); return; }',''),@('out','return actual;','relocatedMembers = 0; return actual;'))){
 if(!$code.Contains($mutation[1])){throw "Missing unsafe target $($mutation[0])"};$changed=$code.Replace('namespace MobDecisionReplay','namespace MobDecisionUnsafe'+$mutation[0]);if($mutation[0]-eq'result'){$changed=$changed.Replace($find,$find.Replace('return actual;','return !actual;'))}elseif($mutation[0]-eq'out'){$changed=$changed.Replace($hidden,$hidden.Replace($mutation[1],$mutation[2]))}elseif($mutation[0]-eq'readScope'){$firstGuardEnd=$write.IndexOf($mutation[1])+$mutation[1].Length;$withoutPost=$write.Substring(0,$firstGuardEnd)+$write.Substring($firstGuardEnd).Replace($mutation[1],'');$changed=$changed.Replace($write,$withoutPost)}else{$changed=$changed.Replace($mutation[1],$mutation[2])};Add-Type -TypeDefinition $changed;$caught=$false;try{([type]('MobDecisionUnsafe'+$mutation[0]+'.Cases')).GetMethod('Run').Invoke($null,@())|Out-Null}catch{$caught=$true};if(!$caught){throw "Unsafe observer survived $($mutation[0])"};$unsafe++
}
"PASS MOB decision observer actual_cases=$cases executed_unsafe=$unsafe single_super_wrappers=3 native_compile=NOT_RUN native_runtime=NOT_RUN"
